from fastapi import FastAPI, HTTPException, status

app = FastAPI()
DB = {}

@app.get("/v1/cuentas/{cuenta_id}/movimientos")
def movimientos(cuenta_id: str, usuario=None):
    # usuario viene del token, ya autenticado
    try:
        cuenta = DB.get(cuenta_id)
        if not cuenta or cuenta.get("propietario_id") != getattr(usuario, "id", None):
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Acceso no autorizado")
        return cuenta["movimientos"]
    except KeyError:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Cuenta no encontrada")
    except Exception:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Error interno al procesar la solicitud")

